    // ══════════════════════════════════════════════════════════════
    // BRAND
    //
    // The form is BUILT FROM the served field registry rather than typed here,
    // so a field added to the kit gets a control without a second edit — and
    // each field states what it reaches, which is the difference between a
    // brand kit and a form nobody consults.
    // ══════════════════════════════════════════════════════════════
    let BRAND_FIELDS_SERVED = [];

    async function loadBrands() {
        const host = document.getElementById('brandList');
        if (!host) return;
        let data;
        try { data = await api('/brands'); }
        catch (err) { host.innerHTML = `<p class="text-sm text-muted">Could not read the brands: ${esc(err.message)}</p>`; return; }
        BRAND_FIELDS_SERVED = data.fields || [];
        state.brandRows = data.brands || [];

        if (!state.brandRows.length) {
            host.innerHTML = '<p class="text-sm text-muted">No brand kits yet. One kit per client, '
                + 'reused across every spot you make for them.</p>';
            return;
        }
        host.innerHTML = state.brandRows.map(b => {
            let palette = [];
            try { palette = JSON.parse(b.palette || '[]'); } catch (_) { palette = []; }
            return `<div class="card" style="margin-bottom:8px;">
                <div class="flex-between" style="gap:8px;flex-wrap:wrap;min-width:0;">
                    <div style="min-width:0;">
                        <strong>${esc(b.name || 'Untitled brand')}</strong>
                        ${b.tone ? `<div class="text-sm text-muted">${esc(b.tone)}</div>` : ''}
                        <div class="tag-row" style="margin-top:6px;align-items:center;">
                            ${palette.filter(c => /^#[0-9a-f]{6}$/i.test(c)).map(c =>
                                `<span title="${esc(c)}" style="display:inline-block;width:18px;height:18px;
                                       border-radius:3px;background:${esc(c)};border:1px solid rgba(255,255,255,0.2);"></span>`).join('')}
                            ${b.cta ? `<span class="tag">${esc(b.cta)}</span>` : ''}
                            ${b.legal_line ? '<span class="tag">legal line</span>' : ''}
                        </div>
                    </div>
                    <div class="card-actions">
                        <button class="btn btn-secondary btn-sm" onclick="openBrand('${b.id}')">Edit</button>
                        <button class="btn btn-secondary btn-sm" onclick="deleteBrand('${b.id}')">Delete</button>
                    </div>
                </div>
            </div>`;
        }).join('');
    }

    /** What a field reaches, said on the field itself. */
    const BRAND_REACH_NOTE = {
        prompt: 'Reaches the generation prompt.',
        compliance: 'Checked before anything generates.',
        handoff: 'Travels into the Premiere package for the editor.',
        person: 'Production paperwork — read by a person, never sent anywhere.',
    };

    const BRAND_JSON_FIELDS = ['palette', 'fonts', 'banned_phrases'];

    function openBrand(id) {
        const b = id ? (state.brandRows || []).find(x => x.id === id) || {} : {};
        const fields = BRAND_FIELDS_SERVED.length ? BRAND_FIELDS_SERVED : [{ id: 'name', label: 'Name', reaches: 'handoff', why: '' }];
        const row = f => {
            const val = b[f.id] || '';
            const note = `<span class="text-sm text-muted">${esc(BRAND_REACH_NOTE[f.reaches] || '')} ${esc(f.why || '')}</span>`;
            if (BRAND_JSON_FIELDS.includes(f.id)) {
                let list = [];
                try { list = JSON.parse(val || '[]'); } catch (_) { list = []; }
                const text = f.id === 'fonts'
                    ? list.map(x => `${x.role || ''}|${x.family || ''}|${x.weight || ''}`).join('\n')
                    : list.join('\n');
                return `<div class="form-group"><label>${esc(f.label)}</label>
                    <textarea id="brand_${f.id}" data-field="${f.id}" rows="3"
                              placeholder="${f.id === 'fonts' ? 'role|family|weight, one per line' : 'one per line'}">${esc(text)}</textarea>
                    ${note}</div>`;
            }
            if (f.id === 'notes' || f.id === 'legal_line' || f.id === 'tone') {
                return `<div class="form-group"><label>${esc(f.label)}</label>
                    <textarea id="brand_${f.id}" data-field="${f.id}" rows="2" maxlength="4000">${esc(val)}</textarea>
                    ${note}</div>`;
            }
            return `<div class="form-group"><label>${esc(f.label)}</label>
                <input type="text" id="brand_${f.id}" data-field="${f.id}" maxlength="1000" value="${esc(val)}">
                ${note}</div>`;
        };
        showModalHtml('brandModal', `
            <div class="modal-header">
                <h3>${id ? 'Edit brand' : 'New brand'}</h3>
                <button class="modal-close" onclick="closeModal('brandModal')">&times;</button>
            </div>
            <div class="modal-body">
                <p class="text-sm text-muted" style="margin-top:0;">
                    Only the tone and the palette reach a generation. The CTA, the legal line and the
                    fonts are words and type that go on screen in Premiere &mdash; asking a diffusion
                    model to render legible text bakes a smudge into a frame you paid for.</p>
                ${fields.map(row).join('')}
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" onclick="closeModal('brandModal')">Cancel</button>
                <button class="btn btn-primary" onclick="saveBrand(${id ? `'${id}'` : 'null'})">Save</button>
            </div>`);
    }

    async function saveBrand(id) {
        const body = {};
        for (const f of BRAND_FIELDS_SERVED) {
            const el = document.getElementById(`brand_${f.id}`);
            if (!el) continue;
            const raw = el.value;
            if (BRAND_JSON_FIELDS.includes(f.id)) {
                const lines = raw.split('\n').map(l => l.trim()).filter(Boolean);
                body[f.id] = JSON.stringify(f.id === 'fonts'
                    ? lines.map(l => {
                        const [role, family, weight] = l.split('|').map(x => (x || '').trim());
                        return { role, family, weight };
                    })
                    : lines);
            } else {
                body[f.id] = raw;
            }
        }
        if (!String(body.name || '').trim()) return setStatus('A brand kit needs a name');
        try {
            await api(id ? `/brands/${id}` : '/brands',
                { method: id ? 'PUT' : 'POST', body: JSON.stringify(body) });
            closeModal('brandModal');
            setStatus(id ? 'Brand updated' : 'Brand added');
            loadBrands();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function deleteBrand(id) {
        if (!confirm('Delete this brand kit?\n\nIt is shared across every project that uses it — '
            + 'projects pointing at it keep their pointer and simply lose the kit.')) return;
        try {
            const out = await api(`/brands/${id}`, { method: 'DELETE' });
            setStatus(out.projects_referencing
                ? `Brand deleted — ${out.projects_referencing} project(s) referenced it`
                : 'Brand deleted');
            loadBrands();
        } catch (err) { setStatus('Error: ' + err.message); }
    }
